const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function toast(t){const x=$('#toast');if(!x)return;x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1700)}
function openRoomsWhatsApp(message){const url=`https://wa.me/26774583606?text=${encodeURIComponent(message)}`;const mobile=window.matchMedia('(max-width:900px)').matches||/Android|iPhone|iPad|iPod/i.test(navigator.userAgent||'');if(mobile){window.location.href=url;return}const popup=window.open(url,'_blank');if(popup){try{popup.opener=null}catch(_){}}else{window.location.href=url}}
function scrollBooking(target=booking){if(!target)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;target.scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'})}
const io=(typeof window.IntersectionObserver==='function')?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -3% 0px'}):null;
$$('.reveal,.scroll-in').forEach(el=>{if(io)io.observe(el);else el.classList.add('visible')});
const booking=document.getElementById('roomBooking');
document.querySelectorAll('[data-room-scroll]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.roomScroll==='rooms'?'roomsOptions':'roomBooking';const x=document.getElementById(id);if(x)scrollBooking(x)}));
const roomBookTop=document.getElementById('roomBookTop');if(roomBookTop)roomBookTop.addEventListener('click',()=>scrollBooking());
const roomForm=document.getElementById('roomBookingForm');
const ROOM_BOOK_SESSION_KEY='lovely-rooms-booking-v1';
function saveRoomBookingSession(){
 if(!roomForm)return;try{sessionStorage.setItem(ROOM_BOOK_SESSION_KEY,JSON.stringify({name:($('#roomGuestName')||{}).value||'',room:($('#roomType')||{}).value||'',checkin:($('#roomCheckIn')||{}).value||'',checkout:($('#roomCheckOut')||{}).value||''}))}catch(_){}
}
function restoreRoomBookingSession(){
 if(!roomForm)return;try{const raw=sessionStorage.getItem(ROOM_BOOK_SESSION_KEY);if(!raw)return;const data=JSON.parse(raw)||{};const guest=$('#roomGuestName'),type=$('#roomType'),ci=$('#roomCheckIn'),co=$('#roomCheckOut');if(guest&&typeof data.name==='string')guest.value=data.name.slice(0,80);if(type&&[...type.options].some(o=>o.value===data.room))type.value=data.room;if(ci&&/^\d{4}-\d{2}-\d{2}$/.test(data.checkin||''))ci.value=data.checkin;if(co&&/^\d{4}-\d{2}-\d{2}$/.test(data.checkout||''))co.value=data.checkout}catch(_){try{sessionStorage.removeItem(ROOM_BOOK_SESSION_KEY)}catch(__){}}
}
let roomBookingBusy=false;
function resetRoomBookingBusy(){roomBookingBusy=false;if(!roomForm)return;const submit=roomForm.querySelector('[type="submit"]');if(submit){submit.removeAttribute('aria-busy');submit.disabled=false}}
function roomEstimateSetup(){
 if(!roomForm)return;
 const ci=$('#roomCheckIn'),co=$('#roomCheckOut'),guest=$('#roomGuestName'),roomSelect=$('#roomType'),estimate=$('#roomEstimate'),formStatus=$('#roomFormStatus');
 const setFormStatus=msg=>{if(formStatus){formStatus.textContent='';requestAnimationFrame(()=>{formStatus.textContent=msg})}};
 const today=new Date();today.setMinutes(today.getMinutes()-today.getTimezoneOffset());const minDate=today.toISOString().slice(0,10);const nextDayISO=value=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value||''));if(!m)return minDate;const d=new Date(Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3])+1,12));return d.toISOString().slice(0,10)};ci.min=minDate;co.min=minDate;restoreRoomBookingSession();if(ci.value&&ci.value<minDate){ci.value='';co.value='';saveRoomBookingSession()}if(ci.value&&co.value&&co.value<=ci.value){co.value='';saveRoomBookingSession()}co.min=ci.value?nextDayISO(ci.value):minDate;if(co.value&&co.value<co.min){co.value='';saveRoomBookingSession()}
 const nightsBetween=(a,b)=>{if(!a||!b||b<=a)return 0;return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)};
 const roomRate=value=>value.includes('P450')?450:value.includes('P300')?300:0;
 const update=()=>{const nights=nightsBetween(ci.value,co.value),rate=roomRate(roomSelect.value),strong=estimate.querySelector('strong'),small=estimate.querySelector('small');if(rate&&nights>0){strong.textContent=`P${(rate*nights).toLocaleString('en-BW')} · ${nights} ${nights===1?'night':'nights'}`;small.textContent='Room-only estimate. Availability and payment instructions are still confirmed on WhatsApp.'}else{strong.textContent='Choose a room and dates';small.textContent='Availability is still confirmed on WhatsApp before payment.'}};
 const persistAndUpdate=()=>{saveRoomBookingSession();update()};
 ci.addEventListener('change',()=>{co.setCustomValidity('');co.min=ci.value?nextDayISO(ci.value):minDate;if(co.value&&co.value<co.min)co.value='';persistAndUpdate()});co.addEventListener('change',()=>{co.setCustomValidity('');persistAndUpdate()});roomSelect.addEventListener('change',persistAndUpdate);guest.addEventListener('input',saveRoomBookingSession);update();
 document.querySelectorAll('.room-enquire').forEach(b=>b.addEventListener('click',()=>{const target=`${b.dataset.roomType} — ${b.dataset.roomRate}`;[...roomSelect.options].forEach(o=>{if(o.value===target)o.selected=true});saveRoomBookingSession();update();scrollBooking();setTimeout(()=>ci.focus({preventScroll:true}),420)}));
 roomForm.addEventListener('submit',e=>{e.preventDefault();if(roomBookingBusy)return;if(!roomForm.checkValidity()){roomForm.reportValidity();setFormStatus('Please complete all required booking fields.');return}const name=guest.value.trim(),room=roomSelect.value,checkin=ci.value,checkout=co.value,nights=nightsBetween(checkin,checkout),rate=roomRate(room);if(nights<1){co.setCustomValidity('Check-out must be after check-in.');co.reportValidity();setFormStatus('Check-out must be after check-in.');toast('Check-out must be after check-in.');return}co.setCustomValidity('');saveRoomBookingSession();roomBookingBusy=true;const submit=roomForm.querySelector('[type="submit"]');if(submit){submit.setAttribute('aria-busy','true');submit.disabled=true}setFormStatus('Opening WhatsApp to send your availability request.');const estimateLine=rate?`Room-only estimate: P${(rate*nights).toLocaleString('en-BW')} (${nights} ${nights===1?'night':'nights'})`:'';const msg=['Hello Lovely Rooms, I would like to check availability:',`Guest: ${name}`,`Room: ${room}`,`Check-in: ${checkin}`,`Check-out: ${checkout}`,estimateLine,'Please confirm availability, the final room-only total and payment instructions. Breakfast can be added separately.'].filter(Boolean).join('\n');openRoomsWhatsApp(msg)});
 window.addEventListener('pagehide',saveRoomBookingSession,{capture:false});window.addEventListener('pageshow',()=>{resetRoomBookingBusy();restoreRoomBookingSession();if(ci.value)co.min=nextDayISO(ci.value);update()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)resetRoomBookingBusy()});window.addEventListener('focus',resetRoomBookingBusy);
}
roomEstimateSetup();
